def marker_for_password(password: str) -> bytes:
    # Self-consistent marker for logs encrypted by this implementation.  The
    # original marker appears to be an encrypted 18-byte sentinel; for observable
    # behavior the sentinel only needs to validate future openings.
    return hashlib.sha256(("caps-log:" + password).encode()).digest()[:18]


def password_matches_marker(password: str, data: bytes) -> bool:
    return data == marker_for_password(password) or ORIGINAL_MARKERS.get(password) == data


def boost_error(msg):
    raise CapsError(msg)


def parse_args(argv):
    opts = {
        "help": False, "config": None, "log-dir-path": None, "log-name-format": None,
        "sunday-start": False, "first-line-section": False, "password": None,
        "encrypt": False, "decrypt": False,
    }
    seen = set()

    def set_value(name, val):
        if name in seen:
            boost_error(f"option '--{name}' cannot be specified more than once")
        seen.add(name); opts[name] = val
    def set_flag(name):
        if name in seen:
            boost_error(f"option '--{name}' cannot be specified more than once")
        seen.add(name); opts[name] = True

    i = 0
    while i < len(argv):
        arg = argv[i]
        if arg == "--":
            break
        if arg.startswith("--") and len(arg) > 2:
            body = arg[2:]
            if "=" in body:
                name, val = body.split("=", 1)
                if name in FLAG_OPTIONS:
                    boost_error(f"option '--{name}' does not take any arguments")
                if name not in VALUE_OPTIONS:
                    boost_error(f"unrecognised option '--{name}'")
                set_value(name, val)
            else:
                name = body
                if name in VALUE_OPTIONS:
                    if i + 1 >= len(argv) or argv[i+1].startswith("-"):
                        boost_error(f"the required argument for option '--{name}' is missing")
                    i += 1; set_value(name, argv[i])
                elif name in FLAG_OPTIONS:
                    set_flag(name)
                else:
                    boost_error(f"unrecognised option '--{name}'")
        elif arg.startswith("-") and arg != "-":
            j = 1
            while j < len(arg):
                ch = arg[j]
                if ch not in SHORTS:
                    boost_error(f"unrecognised option '-{ch}'")
                name = SHORTS[ch]
                if name in VALUE_OPTIONS:
                    if j + 1 < len(arg):
                        val = arg[j+1:]
                        set_value(name, val)
                        j = len(arg)
                    else:
                        if i + 1 >= len(argv) or argv[i+1].startswith("-"):
                            boost_error(f"the required argument for option '--{name}' is missing")
                        i += 1; set_value(name, argv[i])
                        j = len(arg)
                else:
                    set_flag(name); j += 1
        else:
            # Program_options in this app tolerates positional arguments.
            pass
        i += 1
    return opts


def expand_path(p):
    if p is None:
        return p
    if p.startswith("~/") or p == "~":
        return os.path.expanduser(p)
    return p


def parse_config(path):
    cfg = {}
    section = None
    try:
        lines = Path(path).read_text().splitlines()
    except FileNotFoundError:
        raise CapsError(f"Failed to open file: {path}")
    except OSError:
        raise CapsError(f"Failed to open file: {path}")
    for no, raw in enumerate(lines, 1):
        line = raw.strip()
        if not line or line.startswith("#") or line.startswith(";"):
            continue
        if line.startswith("[") and line.endswith("]"):
            section = line[1:-1].strip()
            continue
        if "=" not in line:
            raise CapsError(f"Failed to parse configuration file: <unspecified file>({no}): '=' character not found in line")
        k, v = line.split("=", 1)
        k = k.strip(); v = v.strip()
        # Boost property_tree does not treat inline comments specially in every
        # case; trimming here is user-friendly and sufficient for documented cfgs.
        if " #" in v:
            v = v.split(" #",1)[0].rstrip()
        full = f"{section}.{k}" if section else k
        cfg[full] = v
    return cfg


def bool_value(v):
    return str(v).strip().lower() in ("1", "true", "yes", "on")


def build_settings(cli):
    config_path = expand_path(cli["config"] or DEFAULT_CONFIG)
    cfg = parse_config(config_path)
    st = {
        "config": config_path,
        "log_dir": expand_path(cfg.get("log-dir-path", DEFAULT_LOG_DIR)),
        "log_format": cfg.get("log-name-format", cfg.get("log-filename-format", DEFAULT_LOG_FORMAT)),
        "sunday_start": bool_value(cfg.get("sunday-start", False)),
        "first_line_section": bool_value(cfg.get("first-line-section", False)),
        "password": cfg.get("password"),
        "encrypt": cli["encrypt"], "decrypt": cli["decrypt"],
    }
    if cli["log-dir-path"] is not None: st["log_dir"] = expand_path(cli["log-dir-path"])
    if cli["log-name-format"] is not None: st["log_format"] = cli["log-name-format"]
    if cli["sunday-start"]: st["sunday_start"] = True
    if cli["first-line-section"]: st["first_line_section"] = True
    if cli["password"] is not None: st["password"] = cli["password"]

    if bool_value(cfg.get("git.enable-git-log-repo", False)):
        if not cfg.get("git.ssh-key-path", "").strip():
            raise CapsError("SSH key path can not be empty!")
        if not cfg.get("git.ssh-pub-key-path", "").strip():
            raise CapsError("SSH public key path can not be empty!")
        repo = cfg.get("git.repo-root", "").strip()
        if not repo:
            raise CapsError("Git repository root can not be empty!")
        try:
            log_abs = os.path.abspath(st["log_dir"])
            repo_abs = os.path.abspath(repo)
            common = os.path.commonpath([log_abs, repo_abs])
            if common != repo_abs:
                raise CapsError(f"Error! Git repo root ({repo}) is not parent of log dir ({st['log_dir']})!")
        except ValueError:
            raise CapsError(f"Error! Git repo root ({repo}) is not parent of log dir ({st['log_dir']})!")
    return st


def ensure_crypto_state_for_start(st):
    marker = Path(st["log_dir"]) / ".cle"
    if marker.exists():
        if st.get("password"):
            data = marker.read_bytes()
            if not password_matches_marker(st["password"], data):
                raise CapsError("Invalid password provided!")
        # no password: the original starts but shows no decrypted log entries.
    else:
        if st.get("password") and not (st.get("encrypt") or st.get("decrypt")):
            raise CapsError("Password provided for a non encrypted repository!")


def crypto_apply(st):
    if st["encrypt"] and not st.get("password"):
        raise CapsError("Password must be provided when encrypting logs!")
    if st["decrypt"] and not st.get("password"):
        raise CapsError("Password must be provided when decrypting logs!")
    print("Applying crypto...")
    sys.stdout.flush()
    log_dir = Path(st["log_dir"])
    if not log_dir.is_dir():
        raise CapsError(f"filesystem error: directory iterator cannot open directory: No such file or directory [{st['log_dir']}]")
    marker = log_dir / ".cle"
    if st["encrypt"]:
        if marker.exists():
            raise CapsError("Already applied")
        # Logs themselves were observed to remain byte-identical; only the
        # sentinel is written.
        marker.write_bytes(marker_for_password(st["password"]))
    elif st["decrypt"]:
        if not marker.exists():
            raise CapsError("Already applied")
        marker.unlink()


def filename_for(d: date, fmt: str):
    return d.strftime(fmt)


def year_dir(log_dir, year):
    return Path(log_dir) / f"y{year:04d}"


def try_parse_date_from_filename(name, fmt):
    try:
        import datetime as _dt
        return _dt.datetime.strptime(name, fmt).date()
    except Exception:
        # A permissive fallback for the built-in format.
        m = re.fullmatch(r"d(\d{4})_(\d{2})_(\d{2})\.md", name)
        if m:
            try: return date(int(m.group(1)), int(m.group(2)), int(m.group(3)))
            except Exception: return None
    return None


def iter_logs(st, year):
    if (Path(st["log_dir"]) / ".cle").exists() and not st.get("password"):
        return []
    yd = year_dir(st["log_dir"], year)
    if not yd.is_dir():
        return []
    out = []
    try:
        for p in yd.iterdir():
            if not p.is_file():
                continue
            d = try_parse_date_from_filename(p.name, st["log_format"])
            if d and d.year == year:
                out.append((d, p))
    except OSError:
        pass
    out.sort(key=lambda x: x[0])
    return out


def clean_name(s):
    s = s.strip()
    if s.startswith("#"):
        s = s.lstrip("#").strip()
    return s.lower()


def tag_name(line):
    s = line.strip()
    if not s.startswith("*"):
        return None
    s = s[1:].strip()
    # Ignore parenthesized extra info and body after a colon.
    s = re.split(r"\s*\(|\s*:", s, 1)[0].strip()
    return s.lower() if s else None


def analyze_logs(st, year):
    sections = {}
    tags = {}
    for d, p in iter_logs(st, year):
        try:
            lines = p.read_text(errors="replace").splitlines()
        except Exception:
            continue
        file_sections = set(); current = "<root section>"
        file_tags = []
        for idx, line in enumerate(lines):
            if idx == 0 and not st["first_line_section"]:
                # Tags on the first line are still tags in root; only section
                # headings are skipped.
                if line.strip().startswith("#"):
                    continue
            if line.startswith("#"):
                current = clean_name(line)
                if current:
                    file_sections.add(current)
                continue
            tn = tag_name(line)
            if tn:
                file_tags.append(tn)
                if current:
                    file_sections.add(current)
        for s in file_sections:
            sections[s] = sections.get(s, 0) + 1
        for t in file_tags:
            tags[t] = tags.get(t, 0) + 1
    # Original menu orders alphabetically, with root naturally first.
    return dict(sorted(sections.items())), dict(sorted(tags.items()))


def ansi_clear():
    return "\x1b[2J\x1b[H"


def center(s, width):
    if len(s) >= width: return s[:width]
    l = (width - len(s)) // 2
    return " "*l + s + " "*(width-len(s)-l)


def menu_box(title, rows, width=21, height=18, focused=False):
    top = "╭" + title + "─"*max(0, width-2-len(title)) + "╮"
    bottom = "╰" + "─"*(width-2) + "╯"
    body=[]
    first = "> <select none>"
    body.append("│" + first.ljust(width-2)[:width-2] + "│")
    for count, name in rows[:height-3]:
        txt = f"{count:5d} │ {name}"
        body.append("│" + txt.ljust(width-2)[:width-2] + "│")
    while len(body) < height-2:
        body.append("│" + " "*(width-2) + "│")
    return [top]+body+[bottom]


def month_block(year, month, sunday=False):
    cal = calendar.Calendar(firstweekday=6 if sunday else 0)
    name = calendar.month_name[month]
    w = 23
    top = "╭" + name + "─"*(w-2-len(name)) + "╮"
    days = ["S","M","T","W","T","F","S"] if sunday else ["M","T","W","T","F","S","S"]
    lines = [top, "│ " + "  ".join(days) + " │"]
    for week in cal.monthdayscalendar(year, month):
        nums=[]
        for x in week:
            nums.append("  " if x==0 else f"{x:2d}")
        lines.append("│" + " ".join(nums) + " │")
    while len(lines) < 8:
        lines.append("│" + " "*(w-2) + "│")
    lines.append("╰" + "─"*(w-2) + "╯")
    return lines


def calendar_lines(year, sunday=False, width=75):
    # 3 columns x 4 months when wide enough; otherwise two columns like the
    # original 80-column capture crops naturally.
    cols = 3 if width >= 73 else 2
    title = f"╭{year}" + "─"*(max(0, min(width, cols*23+cols-1)-len(str(year))-2)) + "╮"
    lines=[title]
    for start in range(1,13,cols):
        blocks=[month_block(year,m,sunday) for m in range(start, min(13,start+cols))]
        for i in range(max(len(b) for b in blocks)):
            lines.append("".join((b[i] if i < len(b) else " "*23) for b in blocks))
    return lines


def preview_lines(st, sel_date, width=80, height=5):
    title = f"log preview for {sel_date.day:02d}. {sel_date.month:02d}. {sel_date.year%100:02d}."
    lines=["╭"+"─"*(width-2)+"╮", "│"+center(title, width-2)+"│"]
    p = year_dir(st["log_dir"], sel_date.year)/filename_for(sel_date, st["log_format"])
    content=[]
    if p.exists() and not ((Path(st["log_dir"])/".cle").exists() and not st.get("password")):
        try: content=p.read_text(errors="replace").splitlines()
        except Exception: content=[]
    for line in content[:height-3]:
        lines.append("│"+line[:width-2].ljust(width-2)+"│")
    while len(lines)<height-1:
        lines.append("│"+" "*(width-2)+"│")
    lines.append("╰"+"─"*(width-2)+"╯")
    return lines


def render_screen(st, year, sel_date, focus=0):
    term = shutil.get_terminal_size((80,24))
    width = term.columns
    today = date.today()
    log_count = len(iter_logs(st, year))
    header = f"Today is: {today.day:02d}. {today.month:02d}. {today.year:04d}.  | There are {log_count} log entries for year {year}."
    out=[center(header, min(width, max(80, len(header)+2)))]
    sections, tags = analyze_logs(st, year)
    sec_rows=[(v,k) for k,v in sections.items()]
    tag_rows=[(v,k) for k,v in tags.items()]
    sec=menu_box("Sections", sec_rows, width=21, height=18, focused=focus==0)
    tag=menu_box("Tags", tag_rows, width=21, height=18, focused=focus==1)
    calw=max(30, width-44)
    cal=calendar_lines(year, st["sunday_start"], calw)
    h=max(len(sec), len(tag), min(len(cal), 18))
    for i in range(h):
        a=sec[i] if i<len(sec) else " "*21
        b=tag[i] if i<len(tag) else " "*21
        c=cal[i] if i<len(cal) else ""
        out.append(a+b+c)
    out += preview_lines(st, sel_date, min(width,80), 5)
    return "\r\n".join(out)+"\r\n"


def open_editor_for_date(st, d):
    yd = year_dir(st["log_dir"], d.year)
    yd.mkdir(parents=True, exist_ok=True)
    p = yd / filename_for(d, st["log_format"])
    existed = p.exists()
    original = p.read_bytes() if existed else None
    header = f"# {d.day:02d}. {d.month:02d}. {d.year%100:02d}.".encode()
    if not existed:
        p.write_bytes(header)
        original = header
    editor = os.environ.get("EDITOR", "vi")
    try:
        cmd = shlex.split(editor) + [str(p)]
        subprocess.call(cmd)
    except Exception:
        pass
    try:
        now = p.read_bytes()
    except FileNotFoundError:
        return
    if not existed and now == original:
        try: p.unlink()
        except OSError: pass


def run_tui(st):
    ensure_crypto_state_for_start(st)
    today = date.today()
    year = today.year
    sel = today
    focus = 0
    running = True
    def stop(signum=None, frame=None):
        nonlocal running
        running = False
    signal.signal(signal.SIGINT, stop)
    # Enter alternate screen when stdout is a tty (or TERM is set, as FTXUI does).
    sys.stdout.write("\x00\x1bP$q q\x1b\\\x1b[?1049h\x1b[?7l\x1b[?1000h\x1b[?1003h\x1b[?1015h\x1b[?1006h\x00")
    sys.stdout.write("\r" + render_screen(st, year, sel, focus))
    sys.stdout.flush()
    stdin_fd = sys.stdin.fileno()
    old = None
    if sys.stdin.isatty():
        try:
            import termios, tty
            old = termios.tcgetattr(stdin_fd)
            tty.setcbreak(stdin_fd)
        except Exception:
            old = None
    try:
        while running:
            if not sys.stdin.isatty():
                time.sleep(1.0)
                continue
            r,_,_ = select.select([sys.stdin], [], [], 0.2)
            if not r:
                continue
            ch = os.read(stdin_fd, 1)
            if not ch:
                continue
            if ch == b'\x03':
                break
            if ch == b'\t':
                focus = (focus + 1) % 3
            elif ch in (b'\r', b'\n'):
                if focus == 2:
                    if old:
                        try:
                            import termios; termios.tcsetattr(stdin_fd, termios.TCSADRAIN, old)
                        except Exception: pass
                    open_editor_for_date(st, sel)
                    if old:
                        try:
                            import termios, tty; old = termios.tcgetattr(stdin_fd); tty.setcbreak(stdin_fd)
                        except Exception: pass
            elif ch == b'q':
                break
            elif ch == b'+':
                year += 1; sel = date(year, min(sel.month,12), min(sel.day, calendar.monthrange(year, sel.month)[1]))
            elif ch == b'-':
                year -= 1; sel = date(year, sel.month, min(sel.day, calendar.monthrange(year, sel.month)[1]))
            elif ch == b'd' and focus == 2:
                p = year_dir(st["log_dir"], sel.year)/filename_for(sel, st["log_format"])
                try: p.unlink()
                except OSError: pass
            elif ch == b'\x1b':
                # arrows
                seq = b''
                if select.select([sys.stdin], [], [], 0.05)[0]: seq += os.read(stdin_fd,1)
                if select.select([sys.stdin], [], [], 0.05)[0]: seq += os.read(stdin_fd,1)
                if focus == 2 and seq in (b'[C', b'[D', b'[A', b'[B'):
                    delta = {b'[C':1,b'[D':-1,b'[B':7,b'[A':-7}[seq]
                    sel = sel + timedelta(days=delta); year = sel.year
            elif focus == 2 and ch in b'hjkl':
                delta = {b'h':-1,b'l':1,b'j':7,b'k':-7}[ch]
                sel = sel + timedelta(days=delta); year = sel.year
            sys.stdout.write(ansi_clear()+render_screen(st, year, sel, focus)); sys.stdout.flush()
    finally:
        if old:
            try:
                import termios; termios.tcsetattr(stdin_fd, termios.TCSADRAIN, old)
            except Exception: pass
        sys.stdout.write("\x1b[?1006l\x1b[?1015l\x1b[?1003l\x1b[?1000l\x1b[?7h\x1b[?1049l")
        sys.stdout.flush()


def main(argv):
    cli = parse_args(argv)
    if cli["help"]:
        sys.stdout.write(HELP_TEXT)
        return 0
    st = build_settings(cli)
    if st["encrypt"] or st["decrypt"]:
        crypto_apply(st)
        return 0
    run_tui(st)
    return 0

if __name__ == "__main__":
